def encode(numbers):
    encoded = []

    for number in numbers:
        groups = [number & 0x7F]
        number >>= 7

        while number:
            groups.append((number & 0x7F) | 0x80)
            number >>= 7

        groups.reverse()
        encoded.extend(groups)

    return encoded


def decode(bytes_):
    decoded = []
    value = 0
    sequence_open = False

    for byte in bytes_:
        value = (value << 7) | (byte & 0x7F)

        if byte & 0x80:
            sequence_open = True
        else:
            decoded.append(value)
            value = 0
            sequence_open = False

    if sequence_open:
        raise ValueError("incomplete sequence")

    return decoded

